<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {ElButton,ElInput,ElSelect,ElOption} from 'element-plus'
import type {TaskEntity,TaskListEntity} from '../services/tasks'
import type {ProjectEntity} from '../services/workspace'
import type {TagEntity} from '../services/tags'
import {taskRepeatLabel} from '@note-flow/core/task-recurrence'
import {validTaskWindow} from '../tasks/taskExperience'
import PcDatePicker from './PcDatePicker.vue'
import TaskRepeatEditor from './TaskRepeatEditor.vue'
import MarkdownPreview from './MarkdownPreview.vue'
import TaskPropertyIcon from './TaskPropertyIcon.vue'
import 'element-plus/es/components/button/style/css'
import 'element-plus/es/components/input/style/css'
import 'element-plus/es/components/select/style/css'
import 'element-plus/es/components/option/style/css'

const props=defineProps<{task:TaskEntity;lists:TaskListEntity[];projects:ProjectEntity[];tags:TagEntity[];children:TaskEntity[];relatedCount:number;activityCount:number;saving:boolean;error?:string;save:(changes:Partial<TaskEntity>,original:TaskEntity)=>Promise<void>}>()
const emit=defineEmits<{close:[];more:[event:MouseEvent];complete:[value:boolean];'begin-edit':[];'draft-change':[dirty:boolean];'draft-stamp':[stamp:string];'activity-open':[];'add-child':[];'toggle-child':[task:TaskEntity];'open-child':[task:TaskEntity];'move-child':[task:TaskEntity,offset:number]}>()
const mode=ref<'view'|'edit'>('view'),draft=ref<Partial<TaskEntity>>({}),original=ref<TaskEntity>(),baseline=ref(''),localError=ref(''),moreSettings=ref(false),repeatOpen=ref(false),draggedChild=ref(''),descriptionInput=ref<HTMLTextAreaElement>(),repeatEditor=ref<InstanceType<typeof TaskRepeatEditor>>()
const sections=ref({basic:true,description:true,children:true,related:false,activity:false,source:false})
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const editable=(task:TaskEntity)=>({title:task.title,description:task.description||'',completed:Boolean(task.completed),priority:task.priority||0,startAt:task.startAt?.replace(' ','T')||null,dueAt:task.dueAt?.replace(' ','T')||null,taskListId:task.taskListId??null,taskListUid:task.taskListUid??null,listName:task.listName||'',projectUid:task.projectUid??null,areaUid:task.areaUid??null,tagIds:[...(task.tagIds||[])],reminderOffsetsMinutes:[...(task.reminderOffsetsMinutes||[])],estimatedMinutes:task.estimatedMinutes??null,recurrenceRule:task.recurrenceRule||null})
const dirty=computed(()=>mode.value==='edit'&&JSON.stringify(draft.value)!==baseline.value)
const display=computed(()=>mode.value==='edit'?draft.value:props.task)
const displayTags=computed(()=>props.tags.filter(tag=>display.value.tagIds?.includes(tag.id)))
const completed=computed(()=>props.children.filter(task=>task.completed).length)
const progress=computed(()=>props.children.length?Math.round(completed.value/props.children.length*100):0)
const listName=computed(()=>props.lists.find(list=>list.uid===display.value.taskListUid||list.id===display.value.taskListId)?.name||display.value.listName||'收集箱')
const projectName=computed(()=>props.projects.find(project=>project.uid===display.value.projectUid)?.name||'无所属项目')
const reminderText=computed(()=>display.value.reminderOffsetsMinutes?.length?display.value.reminderOffsetsMinutes.map(value=>value===0?'准时':`提前 ${value} 分钟`).join('、'):'无')
const reminderOptions=[{value:0,label:'准时'},{value:10,label:'提前 10 分钟'},{value:30,label:'提前 30 分钟'},{value:60,label:'提前 1 小时'},{value:1440,label:'提前 1 天'}]
const allReminderOptions=computed(()=>[...reminderOptions,...(draft.value.reminderOffsetsMinutes||[]).filter(value=>!reminderOptions.some(item=>item.value===value)).map(value=>({value,label:`提前 ${value} 分钟`}))])
const dateText=(value?:string|null)=>value?value.replace('T',' ').slice(0,16):'未设置'
const repeatText=computed(()=>display.value.recurrenceRule?taskRepeatLabel(display.value.recurrenceRule):'不重复')
watch(dirty,value=>emit('draft-change',value),{flush:'sync'})
watch(draft,value=>emit('draft-stamp',JSON.stringify(value)),{deep:true,flush:'sync'})
watch(()=>props.task.uid,()=>{mode.value='view';draft.value={};localError.value='';moreSettings.value=false;repeatOpen.value=false;sections.value={basic:true,description:true,children:true,related:false,activity:false,source:false}})
onBeforeUnmount(()=>emit('draft-change',false))
async function beginEdit(section:'basic'|'description'='basic'){
 if(props.saving)return
 if(mode.value!=='edit'){emit('begin-edit');original.value=clone(props.task);draft.value=editable(props.task);baseline.value=JSON.stringify(draft.value);localError.value='';mode.value='edit'}
 sections.value[section]=true
 if(section==='description'){await nextTick();descriptionInput.value?.focus()}
}
function cancel(){if(props.saving)return;mode.value='view';draft.value={};localError.value='';repeatOpen.value=false}
async function submit(){
 localError.value=''
 if(repeatEditor.value&&!repeatEditor.value.valid()){repeatOpen.value=true;await nextTick();repeatEditor.value?.validate();localError.value='请检查重复设置';return}
 if(!draft.value.title?.trim()){localError.value='任务标题不能为空';return}
 if(!validTaskWindow(draft.value.startAt,draft.value.dueAt)){localError.value='截止时间不能早于任务日期';return}
 if(draft.value.reminderOffsetsMinutes?.length&&!draft.value.startAt&&!draft.value.dueAt){localError.value='设置提醒前，请先设置开始或截止时间';return}
 const minutes=draft.value.estimatedMinutes
 if(minutes!=null&&String(minutes)!==''&&(!Number.isInteger(Number(minutes))||Number(minutes)<1||Number(minutes)>10080)){localError.value='预计时长应为 1 至 10080 分钟的整数';return}
 if(!original.value||props.saving)return
 try{await props.save({...clone(draft.value),title:draft.value.title.trim()},original.value);mode.value='view';draft.value={};repeatOpen.value=false}catch(error){const saved=(error as {savedTask?:TaskEntity})?.savedTask;if(saved&&saved.uid===original.value?.uid)original.value=clone(saved);localError.value=error instanceof Error?error.message:'保存失败，请重试'}
}
function chooseList(value:string){const list=props.lists.find(item=>item.uid===value);draft.value={...draft.value,taskListId:list?.id??null,taskListUid:list?.uid??null,listName:list?.name||'收集箱',areaUid:list?.areaUid||draft.value.areaUid,projectUid:list?null:draft.value.projectUid}}
function chooseProject(value:string){const project=props.projects.find(item=>item.uid===value);draft.value={...draft.value,projectUid:value||null,areaUid:project?.areaUid||draft.value.areaUid,...(value?{taskListId:null,taskListUid:null,listName:''}:{})}}
function toggleSection(name:keyof typeof sections.value){sections.value[name]=!sections.value[name];if(name==='activity'&&sections.value.activity)emit('activity-open')}
function dropChild(target:string){const from=props.children.findIndex(task=>task.uid===draggedChild.value),to=props.children.findIndex(task=>task.uid===target);if(from>=0&&to>=0&&from!==to&&!props.saving)emit('move-child',props.children[from],to-from);draggedChild.value=''}
function formatDescription(before:string,after=before){const input=descriptionInput.value;if(!input)return;const value=draft.value.description||'',start=input.selectionStart,end=input.selectionEnd;draft.value.description=value.slice(0,start)+before+value.slice(start,end)+after+value.slice(end);void nextTick(()=>{input.focus();input.setSelectionRange(start+before.length,end+before.length)})}
</script>

<template>
 <section class="task-concept" :class="{'is-editing':mode==='edit'}">
  <header class="task-concept-heading"><h2>{{mode==='edit'?'编辑任务':'任务详情'}}</h2><div><ElButton v-if="mode==='view'" text size="small" aria-label="编辑任务" @click="beginEdit()">编辑</ElButton><ElButton v-if="mode==='view'" text size="small" aria-label="更多任务操作" @click="emit('more',$event)">•••</ElButton><ElButton text size="small" aria-label="关闭任务详情" :disabled="saving" @click="emit('close')">×</ElButton></div></header>
  <div class="task-concept-scroll">
   <section class="task-concept-identity">
    <div class="task-concept-title"><input v-if="mode==='edit'" v-model="draft.completed" type="checkbox" aria-label="任务完成状态" :disabled="saving"/><input v-else type="checkbox" :checked="task.completed" :disabled="saving" aria-label="任务完成状态" @change="emit('complete',($event.target as HTMLInputElement).checked)"/><ElInput v-if="mode==='edit'" v-model="draft.title" aria-label="任务标题" :disabled="saving" maxlength="120"/><h3 v-else>{{task.title}}</h3></div>
    <div class="task-concept-badges"><template v-if="mode==='edit'"><ElSelect v-model="draft.completed" aria-label="任务状态" :disabled="saving"><ElOption :value="false" label="待办"/><ElOption :value="true" label="已完成"/></ElSelect><ElSelect v-model="draft.priority" aria-label="任务优先级" :disabled="saving"><ElOption :value="0" label="普通"/><ElOption :value="1" label="中优先级"/><ElOption :value="2" label="重要"/></ElSelect><ElSelect v-model="draft.tagIds" multiple filterable collapse-tags aria-label="任务标签" placeholder="添加标签" :disabled="saving"><ElOption v-for="tag in tags" :key="tag.id" :value="tag.id" :label="tag.name"/></ElSelect></template><template v-else><span class="state">{{task.abandonedAt?'已放弃':task.completed?'已完成':'待办'}}</span><span :class="{important:task.priority===2}">{{task.priority===2?'重要':task.priority===1?'中优先级':'普通'}}</span><span v-for="tag in displayTags" :key="tag.id">{{tag.name}}</span></template></div>
   </section>
   <section class="task-concept-block"><header><button class="task-block-toggle" :aria-expanded="sections.basic" @click="toggleSection('basic')"><i :class="{expanded:sections.basic}"/>基本信息</button><ElButton v-if="mode==='view'" text size="small" @click="beginEdit('basic')">编辑基本信息</ElButton></header>
    <div v-show="sections.basic" class="task-concept-info">
     <div class="task-info-column"><label><TaskPropertyIcon name="calendar"/><span>开始时间</span><PcDatePicker v-if="mode==='edit'" v-model="draft.startAt" include-time :teleported="false" aria-label="开始时间" :disabled="saving"/><b v-else>{{dateText(task.startAt)}}</b></label><label><TaskPropertyIcon name="calendar"/><span>截止时间</span><PcDatePicker v-if="mode==='edit'" v-model="draft.dueAt" include-time :teleported="false" aria-label="截止时间" :disabled="saving"/><b v-else>{{dateText(task.dueAt)}}</b></label><label><TaskPropertyIcon name="bell"/><span>提醒时间</span><ElSelect v-if="mode==='edit'" v-model="draft.reminderOffsetsMinutes" multiple collapse-tags aria-label="提醒时间" placeholder="无" :disabled="saving"><ElOption v-for="item in allReminderOptions" :key="item.value" :value="item.value" :label="item.label"/></ElSelect><b v-else>{{reminderText}}</b></label><label><TaskPropertyIcon name="repeat"/><span>重复</span><ElButton v-if="mode==='edit'" text size="small" aria-label="设置重复" :disabled="saving" @click="repeatOpen=!repeatOpen">{{repeatText}} · 设置</ElButton><b v-else>{{repeatText}}</b></label></div>
     <div class="task-info-column"><label><TaskPropertyIcon name="folder"/><span>所属清单</span><ElSelect v-if="mode==='edit'" :model-value="draft.taskListUid||lists.find(list=>list.id===draft.taskListId)?.uid||''" placeholder="收集箱" :empty-values="[null,undefined]" aria-label="所属清单" :disabled="saving" @change="chooseList"><ElOption value="" label="收集箱"/><ElOption v-for="list in lists" :key="list.uid" :value="list.uid" :label="list.name"/></ElSelect><b v-else>{{listName}}</b></label><label><TaskPropertyIcon name="folder"/><span>所属项目</span><ElSelect v-if="mode==='edit'" :model-value="draft.projectUid||''" clearable filterable placeholder="无所属项目" :empty-values="[null,undefined]" aria-label="所属项目" :disabled="saving" @change="chooseProject"><ElOption value="" label="无所属项目"/><ElOption v-for="project in projects.filter(p=>p.status!=='archived'||p.uid===draft.projectUid)" :key="project.uid" :value="project.uid" :label="project.name"/></ElSelect><b v-else>{{projectName}}</b></label><label><TaskPropertyIcon name="tag"/><span>标签</span><b>{{displayTags.map(tag=>tag.name).join('、')||'无'}}</b></label><button class="task-more-settings" :aria-expanded="moreSettings" @click="moreSettings=!moreSettings">{{moreSettings?'收起更多设置':'更多设置'}} <i :class="{expanded:moreSettings}"/></button></div>
     <div v-if="mode==='edit'" v-show="repeatOpen" class="task-repeat-draft"><TaskRepeatEditor ref="repeatEditor" :rule="draft.recurrenceRule" :saving="saving" draft-mode @change="value=>{draft.recurrenceRule=value}"/><small>保存任务时生效</small></div>
     <div v-if="moreSettings" class="task-more-settings-fields"><label>预计时长（分钟）<ElInput v-if="mode==='edit'" v-model.number="draft.estimatedMinutes" type="number" :min="1" :max="10080" aria-label="预计时长" :disabled="saving"/><b v-else>{{task.estimatedMinutes?`${task.estimatedMinutes} 分钟`:'未设置'}}</b></label><label>创建时间<b>{{dateText(task.createdAt)}}</b></label><label>更新时间<b>{{dateText(task.updatedAt)}}</b></label></div>
    </div>
   </section>
   <section class="task-concept-block"><header><button class="task-block-toggle" :aria-expanded="sections.description" @click="toggleSection('description')"><i :class="{expanded:sections.description}"/>描述</button><ElButton v-if="mode==='view'" text size="small" @click="beginEdit('description')">编辑描述</ElButton></header><div v-show="sections.description" class="task-description-content"><div v-if="mode==='edit'" class="task-description-editor"><div class="task-description-toolbar"><ElButton text size="small" aria-label="加粗" :disabled="saving" @click="formatDescription('**')"><b>B</b></ElButton><ElButton text size="small" aria-label="斜体" :disabled="saving" @click="formatDescription('*')"><i>I</i></ElButton><ElButton text size="small" aria-label="添加列表" :disabled="saving" @click="formatDescription('- ','')">列表</ElButton><ElButton text size="small" aria-label="添加链接" :disabled="saving" @click="formatDescription('[','](https://)')">链接</ElButton></div><textarea ref="descriptionInput" v-model="draft.description" aria-label="任务描述" :disabled="saving" rows="5" placeholder="补充目标、背景或完成标准…"/></div><MarkdownPreview v-else-if="task.description" :content="task.description"/><p v-else class="task-concept-empty">暂无描述</p></div></section>
   <section class="task-concept-block"><header><button class="task-block-toggle" :aria-expanded="sections.children" @click="toggleSection('children')"><i :class="{expanded:sections.children}"/>子任务 <small>{{completed}}/{{children.length}}</small></button><ElButton text size="small" :disabled="saving" @click="emit('add-child')">＋ 添加子任务</ElButton></header><div v-show="sections.children"><div v-if="children.length" class="task-subtask-progress"><progress :value="completed" :max="children.length"/><small>{{progress}}%</small></div><div v-for="(child,index) in children" :key="child.uid" class="task-concept-child" @dragover.prevent @drop.prevent="dropChild(child.uid)"><span class="task-child-grip" aria-hidden="true" :draggable="!saving" @dragstart="draggedChild=child.uid" @dragend="draggedChild=''">⠿</span><input type="checkbox" :checked="child.completed" :disabled="saving" :aria-label="`完成子任务 ${child.title}`" @change="emit('toggle-child',child)"/><button :class="{done:child.completed}" :disabled="saving||dirty" @click="emit('open-child',child)">{{child.title}}</button><time>{{dateText(child.dueAt||child.startAt)}}</time><ElButton text size="small" :disabled="saving||index===0" :aria-label="`上移子任务 ${child.title}`" @click="emit('move-child',child,-1)">↑</ElButton><ElButton text size="small" :disabled="saving||index===children.length-1" :aria-label="`下移子任务 ${child.title}`" @click="emit('move-child',child,1)">↓</ElButton></div><p v-if="!children.length" class="task-concept-empty">暂无子任务</p></div></section>
   <section v-for="block in [{key:'related',label:'关联内容',count:relatedCount},{key:'activity',label:'活动记录',count:activityCount},{key:'source',label:'来源信息',count:undefined}] as const" :key="block.key" class="task-concept-block task-secondary-block"><header><button class="task-block-toggle" :aria-expanded="sections[block.key]" @click="toggleSection(block.key)"><i :class="{expanded:sections[block.key]}"/>{{block.label}} <small v-if="block.count!==undefined">{{block.count}}</small></button></header><div v-if="sections[block.key]" class="task-secondary-content"><slot :name="block.key"/></div></section>
  </div>
  <footer class="task-concept-footer"><p v-if="localError||error" role="alert">{{localError||error}}</p><template v-if="mode==='edit'"><span class="task-draft-status">{{dirty?'有未保存的修改':'尚未修改'}}</span><ElButton :disabled="saving" @click="cancel">取消</ElButton><ElButton type="primary" :disabled="!dirty" :loading="saving" @click="submit">保存修改</ElButton></template><template v-else><small>最后更新：{{dateText(task.updatedAt)}}</small><ElButton text @click="emit('close')">关闭</ElButton></template></footer>
 </section>
</template>

<style scoped>
.task-concept{display:flex;flex-direction:column;height:min(88dvh,920px);min-height:0;color:var(--pc-text);font-size:13px}
.task-concept-heading{display:flex;align-items:center;justify-content:space-between;flex:none;padding:14px 22px 8px}.task-concept-heading h2{margin:0;font-size:14px;font-weight:600}.task-concept-heading>div{display:flex;gap:4px}
.task-concept-scroll{flex:1;min-height:0;overflow:auto;padding:0 24px 20px;overscroll-behavior:contain}
.task-concept-title{display:flex;align-items:flex-start;gap:12px;min-height:34px}.task-concept-title>input{margin:7px 0 0;width:17px;height:17px;accent-color:var(--pc-primary);flex-shrink:0}.task-concept-title h3{margin:3px 0;font-size:19px;line-height:1.5;overflow-wrap:anywhere;font-weight:600}.task-concept-title :deep(.el-input){flex:1}
.task-concept-identity{padding:2px 0 12px}.task-concept-badges{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin:8px 0 0 29px}.task-concept-badges>span{padding:4px 9px;background:#f2f5f6;border-radius:5px;font-size:11px}.task-concept-badges>.state{background:var(--pc-primary-soft);color:var(--pc-primary)}.task-concept-badges>.important{background:#fff0ef;color:#b34747}.task-concept-badges :deep(.el-select){width:106px}.task-concept-badges :deep(.el-select:last-child){width:210px}
.task-concept-block{margin:10px 0 0}.task-concept-block>header{display:flex;align-items:center;justify-content:space-between;min-height:34px;margin:0 0 6px}.task-block-toggle{display:flex;align-items:center;gap:8px;min-height:32px;padding:0;border:0;background:transparent;color:var(--pc-text);font:inherit;font-size:13px;font-weight:600;text-align:left;cursor:pointer}.task-block-toggle small{font-size:11px;font-weight:400;color:var(--pc-muted)}
i:not(.task-description-toolbar i){font-style:normal}.task-block-toggle>i,.task-more-settings>i{display:block;width:6px;height:6px;margin:0 3px;border:solid var(--pc-muted);border-width:0 1px 1px 0;transform:rotate(-45deg);transition:transform .15s}.task-block-toggle>i.expanded,.task-more-settings>i.expanded{transform:rotate(45deg)}
.task-concept-info{display:grid;grid-template-columns:1fr 1fr;gap:12px}.task-info-column{padding:6px 12px;border:1px solid var(--pc-border);border-radius:7px;min-width:0}.task-info-column>label{display:grid;grid-template-columns:17px 68px minmax(0,1fr);align-items:center;gap:8px;min-height:34px;font-size:12px}.task-info-column :deep(.task-property-icon){width:16px;height:16px;padding:0;border:0;background:transparent}.task-info-column :deep(.task-property-icon svg){width:15px;height:15px}.task-info-column label>span{color:var(--pc-muted)}.task-info-column b{min-width:0;font-size:12px;font-weight:400;overflow-wrap:anywhere}.task-info-column :deep(.el-select),.task-info-column :deep(.pc-date-picker){width:100%;min-width:0}.task-info-column :deep(.el-input__inner),.task-info-column :deep(.el-select__selected-item){font-size:12px}.task-info-column :deep(.el-button){justify-self:start;font-size:12px;white-space:normal}
.task-more-settings{display:flex;align-items:center;gap:8px;min-height:34px;padding:0;border:0;background:transparent;color:var(--pc-muted);font:inherit;font-size:12px;cursor:pointer}.task-more-settings-fields{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding:10px 12px;border:1px solid var(--pc-border);border-radius:7px}.task-more-settings-fields>label{display:grid;gap:6px;color:var(--pc-muted);font-size:12px}.task-more-settings-fields b{font-size:12px;font-weight:400;color:var(--pc-text)}.task-repeat-draft{grid-column:1/-1;border:1px solid var(--pc-border);padding:12px;border-radius:7px}.task-repeat-draft>small{color:var(--pc-muted)}
.task-description-content{padding:10px 12px;border:1px solid var(--pc-border);border-radius:7px;min-height:54px;overflow-wrap:anywhere}.task-description-content :deep(.markdown-preview){font-size:13px;line-height:1.75}.task-description-content :deep(p){margin:0 0 6px}.task-description-editor textarea{display:block;width:100%;min-height:110px;padding:9px 2px;box-sizing:border-box;border:0;outline:none;background:transparent;color:var(--pc-text);font:inherit;line-height:1.75;resize:vertical}.task-description-toolbar{display:flex;gap:2px;border-bottom:1px solid var(--pc-border);padding:0 0 5px}.task-concept-empty{margin:8px 0;color:var(--pc-muted);font-size:12px}
.task-subtask-progress{display:flex;align-items:center;gap:16px;margin:6px 8px 10px}.task-subtask-progress progress{flex:1;width:100%;height:6px;accent-color:var(--pc-primary);border:0;border-radius:4px;overflow:hidden}.task-subtask-progress progress::-webkit-progress-bar{background:#edf1ee}.task-subtask-progress progress::-webkit-progress-value{background:var(--pc-primary);border-radius:4px}.task-subtask-progress small{font-size:11px;color:var(--pc-muted)}.task-concept-child{display:flex;gap:10px;align-items:center;min-height:38px;border-bottom:1px solid var(--pc-border)}.task-concept-child>input{width:15px;height:15px;accent-color:var(--pc-primary)}.task-concept-child>button:not(.el-button){flex:1;min-width:0;text-align:left;padding:0;border:0;background:transparent;font:inherit;color:var(--pc-text);overflow-wrap:anywhere;cursor:pointer}.task-concept-child .done{text-decoration:line-through;color:var(--pc-muted)!important}.task-concept-child time{font-size:11px;color:var(--pc-muted)}.task-child-grip{color:var(--pc-muted);cursor:grab}.task-concept-child :deep(.el-button){margin:0;padding:4px;min-width:26px}
.task-secondary-block{border:1px solid var(--pc-border);border-radius:7px;margin-top:8px}.task-secondary-block>header{margin:0;padding:2px 12px}.task-secondary-block .task-block-toggle{width:100%}.task-secondary-content{padding:2px 12px 12px}.task-concept-footer{display:flex;align-items:center;gap:9px;flex-wrap:wrap;flex:none;padding:10px 22px;border-top:1px solid var(--pc-border)}.task-concept-footer>p{width:100%;margin:0;font-size:12px;color:var(--pc-danger,#b34747)}.task-draft-status,.task-concept-footer>small{flex:1;color:var(--pc-muted);font-size:11px}
@media(max-width:650px){.task-concept-info{grid-template-columns:1fr}.task-concept-scroll{padding:0 16px 16px}.task-more-settings-fields{grid-template-columns:1fr}.task-concept-child time{display:none}.task-concept{height:90dvh}}
</style>
